package com.ethk3.novaonepro.strategyv2;
import java.io.*;import java.util.*;import java.security.*;import java.nio.*;
public final class WireParity {
 public static void main(String[] args)throws Exception{MessageDigest digest=MessageDigest.getInstance("SHA-256");for(String family:new String[]{"F13","F14"})for(int seed:new int[]{1,29,1314}){Random random=new Random(seed);SymbolicFamilyR26 m=new SymbolicFamilyR26(family);for(int i=0;i<150;i++){if(i==37||i==110)m.resetTemporalContext();int[] d=new int[10];for(int p=0;p<10;p++)d[p]=p+1;for(int p=9;p>0;p--){int j=random.nextInt(p+1),x=d[p];d[p]=d[j];d[j]=x;}m.update(d);ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(b);m.write(out);byte[] raw=b.toByteArray();if(ByteBuffer.wrap(raw).getInt()==0x26131402){byte[] projected=Arrays.copyOf(raw,raw.length-9);ByteBuffer.wrap(projected).putInt(0x26131401);b.reset();out.write(projected);}float[][] prediction=new float[10][10];float[] state=new float[2];m.predict(prediction,state);for(float[] row:prediction)for(float x:row)out.writeFloat(x);for(float x:state)out.writeFloat(x);digest.update(b.toByteArray());if(i==75){m=new SymbolicFamilyR26(family);m.read(new DataInputStream(new ByteArrayInputStream(raw)));}}}StringBuilder hex=new StringBuilder();for(byte x:digest.digest())hex.append(String.format("%02x",x&255));System.out.println("F13_F14_OLD_NUMERIC_WIRE_ALL_PREDICTIONS_6X150="+hex);}
}
